</aside></div>
<script>
(function () {
  var f = document.getElementById('dx-form'); if (!f) return;
  var w = document.getElementById('dx-what'), from = document.getElementById('dx-from'), to = document.getElementById('dx-to');
  function sync() { var o = w.options[w.selectedIndex]; var url = o.value.split('?'); f.action = url[0]; f.querySelectorAll('[data-extra]').forEach(function (x) { x.remove(); });
    if (url[1]) url[1].split('&').forEach(function (kv) { var p = kv.split('='); var i = document.createElement('input'); i.type = 'hidden'; i.name = decodeURIComponent(p[0]); i.value = decodeURIComponent(p[1] || ''); i.setAttribute('data-extra', '1'); f.appendChild(i); });
    var r = o.getAttribute('data-range') === '1'; document.getElementById('dx-dates').style.display = r ? '' : 'none'; document.getElementById('dx-quick').style.display = r ? '' : 'none'; document.getElementById('dx-range').disabled = !r; }
  w.addEventListener('change', sync);
  document.getElementById('dx-quick').addEventListener('click', function (e) { var b = e.target.closest('[data-days]'); if (!b) return; var t = new Date(); var s = new Date(Date.now() - b.getAttribute('data-days') * 864e5); to.value = t.toISOString().slice(0, 10); from.value = s.toISOString().slice(0, 10); this.querySelectorAll('button').forEach(function (x) { x.classList.toggle('on', x === b); }); });
  f.addEventListener('submit', function () { document.getElementById('dx-range').value = from.value.replace(/-/g, '/') + ' - ' + to.value.replace(/-/g, '/'); setTimeout(function () { location.reload(); }, 2500); });
  sync();
})();
</script>
